using UnityEngine;
using UnityEditor;
using System;
using System.IO;
using System.Linq;
using System.Text;
using ConRoi.Investigation.V36.R103;
using Object = UnityEngine.Object;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            if (!EditorApplication.isPlaying)
                throw new Exception("Play required");
            s.SaveDirectoryOverride = Path.GetFullPath("Test/KetQua/investigation_r103/route-profile");
            if (!s.Load())
                throw new Exception("Completed route save missing");
            s.SaveDirectoryOverride = Path.GetFullPath("Test/KetQua/investigation_r103/review-profile");
            var w = EditorWindow.GetWindow(Type.GetType("UnityEditor.GameView,UnityEditor"));
            var pages = new[]{"shoeprint", "shoe", "shoecontrol", "fabric", "coat", "mechanism", "cipher", "compare", "reconstruction", "conclusions"};
            int step = 0, res = 0;
            bool capture = false;
            double next = 0;
            var log = new StringBuilder("Layout API fixtures only, page held until screenshot finishes.\n");
            EditorApplication.CallbackFunction tick = null;
            tick = () =>
            {
                if (EditorApplication.timeSinceStartup < next)
                    return;
                next = EditorApplication.timeSinceStartup + .65;
                try
                {
                    if (step == 0 && !capture)
                    {
                        var z = res == 0 ? new Vector2(1024, 597.2f) : new Vector2(1536, 885.2f);
                        w.minSize = w.maxSize = z;
                        w.position = new Rect(0, 0, z.x, z.y);
                        w.Focus();
                    }

                    if (!capture)
                    {
                        string p = pages[step];
                        if (step < 6)
                        {
                            s.Acquire(p);
                            s.OpenEvidence(p);
                        }
                        else
                            s.OpenPage(p);
                        capture = true;
                        return;
                    }

                    ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r103/ui-" + (res == 0 ? "720" : "1080") + "-" + pages[step] + ".png");
                    log.AppendLine(pages[step] + " " + Screen.width + "x" + Screen.height);
                    capture = false;
                    step++;
                    if (step == pages.Length)
                    {
                        if (res == 0)
                        {
                            res = 1;
                            step = 0;
                            return;
                        }

                        EditorApplication.update -= tick;
                        File.WriteAllText("Test/KetQua/investigation_r103/ui-layout.txt", log.ToString());
                    }
                }
                catch (Exception e)
                {
                    EditorApplication.update -= tick;
                    File.WriteAllText("Test/KetQua/investigation_r103/ui-layout.txt", log + "FAIL " + e);
                }
            };
            EditorApplication.update += tick;
            r.Log("Final stable two-resolution capture");
        }
    }
}

